F=".first-principles/analysis-20261009T225926Z.md"; R="${F%/*}/report-${F##*/analysis-}"; { printf '# '; cat <<'FP_EOF'
Redis Cache vs Postgres Upgrade Decision
FP_EOF
printf '\n*First-principles analysis · %s*\n\n' "$(date -u '+%-d %B %Y')"
printf '*Read with: [How to read this analysis]''(HOW-TO-READ.md) · [Working file]''(%s) · [All files]''(INDEX.md)*\n\n' "${F##*/}"; awk '
/^```/ { f = !f }
!f && /^## Appendix — process output$/ { exit }
!f && /^\*\*Disclosed:\*\*/ { skip = 1 }
skip && /^#/ { skip = 0 }
skip { if ($0 == "") skip = 0; next }
!f && /^\*\*Pre-check:\*\*/ { next }
!f && /^## Answer$/ { $0 = "## Executive Summary" }
!f && (/^#/ || /^\*\*/) && prev != "" { print "" }
{ print; prev = $0 }' "$F" | cat -s; } > "$R" && echo "$R"

